import { useRouter } from 'expo-router';
import { Pressable, ScrollView, StyleSheet, View } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { Radius, Spacing } from '@/constants/theme';
import { formatCurrency } from '@/domain/currency';
import { formatDate } from '@/domain/date';
import type { Transaction } from '@/domain/types';
import { PrivacyValue } from '@/features/privacy/privacy-value';
import { useTheme } from '@/hooks/use-theme';

/**
 * A transaction that cannot be edited.
 *
 * Trade Republic bonus rows (saveback and round-up) are generated by the import
 * and protected by RLS, so the edit form would only ever fail on save. The web
 * app disables its form for them with the same explanation; showing the facts
 * and the reason is the equivalent here, with a way back to the card payment
 * they came from.
 */
export function ReadOnlyTransaction({ transaction }: { transaction: Transaction }) {
  const theme = useTheme();
  const router = useRouter();

  const color =
    transaction.is_money_transfer ? theme.transfer
    : transaction.type === 'income' ? theme.income
    : theme.expense;

  return (
    <ScrollView contentContainerStyle={styles.content}>
      <View style={[styles.note, { backgroundColor: theme.backgroundElement }]}>
        <ThemedText themeColor="textSecondary" style={styles.noteText}>
          Generated by Trade Republic import — cannot be edited or deleted.
        </ThemedText>
      </View>

      <View style={[styles.card, { backgroundColor: theme.card, borderColor: theme.separator }]}>
        <ThemedText style={styles.title}>{transaction.title}</ThemedText>
        <PrivacyValue
          hidden={transaction.type === 'income'}
          style={[styles.amount, { color }]}>
          {formatCurrency(transaction.eur_amount ?? transaction.amount, 'EUR')}
        </PrivacyValue>
        <Detail label="Category" value={`${transaction.main_category} · ${transaction.sub_category}`} />
        <Detail label="Date" value={formatDate(transaction.date)} />
      </View>

      {transaction.parent_transaction_id ? (
        <Pressable
          onPress={() => router.replace(`/transaction/${transaction.parent_transaction_id}`)}
          accessibilityRole="button"
          style={[styles.link, { borderColor: theme.separator }]}>
          <ThemedText type="link">View original transaction</ThemedText>
        </Pressable>
      ) : null}
    </ScrollView>
  );
}

function Detail({ label, value }: { label: string; value: string }) {
  return (
    <View style={styles.detail}>
      <ThemedText themeColor="textSecondary" style={styles.detailLabel}>
        {label}
      </ThemedText>
      <ThemedText style={styles.detailValue}>{value}</ThemedText>
    </View>
  );
}

const styles = StyleSheet.create({
  content: {
    padding: Spacing.three,
    gap: Spacing.three,
  },
  note: {
    padding: Spacing.three,
    borderRadius: Radius.medium,
  },
  noteText: {
    fontSize: 14,
  },
  card: {
    padding: Spacing.three,
    borderRadius: Radius.medium,
    borderWidth: StyleSheet.hairlineWidth,
    gap: Spacing.two,
  },
  title: {
    fontSize: 17,
    fontWeight: '600',
    textTransform: 'uppercase',
  },
  amount: {
    fontSize: 24,
    fontWeight: '700',
    fontVariant: ['tabular-nums'],
  },
  detail: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    gap: Spacing.two,
  },
  detailLabel: {
    fontSize: 14,
  },
  detailValue: {
    flexShrink: 1,
    fontSize: 14,
    textAlign: 'right',
  },
  link: {
    alignItems: 'center',
    padding: Spacing.three,
    borderRadius: Radius.medium,
    borderWidth: StyleSheet.hairlineWidth,
  },
});
